def solve(alarm_times):
    def parse_time(t):
        h, m = map(int, t.split(':'))
        return h * 60 + m

    def format_interval(minutes):
        hours = minutes // 60
        mins = minutes % 60
        return f"{hours:02d}:{mins:02d}"

    if not alarm_times:
        return "24:00"

    unique_minutes = set()
    for t in alarm_times:
        unique_minutes.add(parse_time(t))

    sorted_times = sorted(unique_minutes)
    n = len(sorted_times)

    if n == 1:
        # Only one alarm, interval is from that time to next day same time minus 1 minute
        # Since alarm rings for 1 minute, next alarm is at (time + 1440) - 1
        # But actually, if alarm is at T, it rings [T, T+1). Next alarm is at T_next.
        # Interval is T_next - (T + 1).
        # For single alarm, next is T + 1440. So interval = (T + 1440) - (T + 1) = 1439 minutes.
        return format_interval(1439)

    max_gap = 0
    for i in range(n):
        current = sorted_times[i]
        next_idx = (i + 1) % n
        next_t = sorted_times[next_idx]

        if next_idx == 0:
            # Wrap around midnight
            diff = (next_t + 1440) - current
        else:
            diff = next_t - current

        # Alarm rings for 1 minute, so effective end of current alarm is current + 1
        # Gap is next_start - (current_end) = next_t - (current + 1)
        gap = diff - 1
        if gap > max_gap:
            max_gap = gap

    return format_interval(max_gap)
